-- Staging-only original MySQL utf8_general_ci username comparison keys.
-- Derivation: WEIGHT_STRING on every valid BMP codepoint in original MySQL.
-- Contains ONLY Unicode codepoint weights (no usernames/credentials).
-- Requires existing private acfun_legacy.users table; do not expose to clients.
BEGIN;
CREATE TABLE IF NOT EXISTS acfun_legacy.mysql_utf8_ci_weights (
  codepoint integer PRIMARY KEY CHECK (codepoint BETWEEN 0 AND 65535),
  weight integer NOT NULL CHECK (weight BETWEEN 0 AND 65535)
);
ALTER TABLE acfun_legacy.mysql_utf8_ci_weights ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON acfun_legacy.mysql_utf8_ci_weights FROM PUBLIC,anon,authenticated,service_role;
