CREATE OR REPLACE FUNCTION acfun_legacy.mysql_username_weight_key(value text)
RETURNS text LANGUAGE SQL STABLE SECURITY INVOKER SET search_path='' AS $fn$
SELECT CASE
 WHEN $1 IS NULL OR EXISTS (
  SELECT 1 FROM unnest(string_to_array(rtrim($1,' '),NULL)) AS x(ch)
  WHERE ascii(x.ch)>65535
 ) THEN NULL
 ELSE COALESCE((
  SELECT string_agg(lpad(to_hex(COALESCE(w.weight,ascii(x.ch))),4,'0'),'' ORDER BY x.ord)
  FROM unnest(string_to_array(rtrim($1,' '),NULL)) WITH ORDINALITY AS x(ch,ord)
  LEFT JOIN acfun_legacy.mysql_utf8_ci_weights w ON w.codepoint=ascii(x.ch)
 ),'')
END;
$fn$;
REVOKE ALL ON FUNCTION acfun_legacy.mysql_username_weight_key(text) FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE IF NOT EXISTS acfun_legacy.username_weight_index (
 uid integer PRIMARY KEY REFERENCES acfun_legacy.users(uid) ON DELETE CASCADE,
 legacy_weight_key text NOT NULL UNIQUE
);
ALTER TABLE acfun_legacy.username_weight_index ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON acfun_legacy.username_weight_index FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO acfun_legacy.username_weight_index(uid,legacy_weight_key)
SELECT uid,acfun_legacy.mysql_username_weight_key(username)
FROM acfun_legacy.users
ON CONFLICT(uid) DO NOTHING;
COMMIT;